1000:    double signal_frequency(bool using_structured_grid)
1001:    // Remember to use stringent_cfl=true for unstructured-grid.
1002:    {
1003:        number signal = 0; // Signal speed is something like a frequency, with units 1/s.
1004:        //
1005:        // Check the convective/wave-driven time step limit first,
1006:        // then add a component to ensure viscous stability.
1007:        //
1008:        // Look at gas-dynamic signal speeds along each face.
1009:        // This works for gas-dynamics only (not MHD), on a structured grid.
1010:        //
1011:        // Get the local normal velocities by rotating the local frame of reference.
1012:        // Also, compute the velocity magnitude and recall the minimum length.
1013:        size_t first_face = 0; // west, assuming quad or hex cells from a structured grid conversion
1014:        size_t second_face = 1; // south, assuming quad or hex cells from a structured grid conversion
1015:        size_t third_face = iface.length - 1; // will be Face.top for structured grid
1016:        if (using_structured_grid) {
1017:            first_face = Face.north;
1018:            second_face = Face.east;
1019:        }
1020:        number un_N = fabs(fs.vel.dot(iface[first_face].n));
1021:        number un_E = fabs(fs.vel.dot(iface[second_face].n));
1022:        number un_T = (myConfig.dimensions == 3) ? fabs(fs.vel.dot(iface[third_face].n)) : to!number(0.0);
1023:        if (myConfig.stringent_cfl) {
1024:            // Compute the speed with the shortest length and the highest speed.
1025:            number un_max = fmax(un_N, un_E);
1026:            number minLength = fmin(iLength, jLength);
1027:            if (myConfig.dimensions == 3) {
1028:                un_max = fmax(un_max, un_T);
1029:                minLength = fmin(minLength, kLength);
1030:            }
1031:            signal = (un_max + fs.gas.a) / minLength;
1032:        } else {
1033:            // Compute the signal speed in each index direction.
1034:            number signalN = (un_N + fs.gas.a) / jLength;
1035:            signal = fmax(signal, signalN);
1036:            number signalE = (un_E + fs.gas.a) / iLength;
1037:            signal = fmax(signal, signalE);
1038:            if (myConfig.dimensions == 3) {
1039:                number signalT = (un_T + fs.gas.a) / kLength;
1040:                signal = fmax(signal, signalT);
1041:            }
1042:        }
1043:        this.signal_hyp = signal; // store hyperbolic signal for STS
1044:        // Factor for the viscous time limit.
1045:        // See Swanson, Turkel and White (1991)
1046:        // This factor is not included if viscosity is zero.
1047:        if (myConfig.viscous && (fs.gas.mu > 10.0e-23)) {
1048:            auto gmodel = myConfig.gmodel;
1049:            number gam_eff = gmodel.gamma(fs.gas);
1050:            // Need to sum conductivities for thermal nonequilibrium.
1051:            number k_total = fs.gas.k;
1052:            version(multi_T_gas) {
1053:                foreach(k_value; fs.gas.k_modes) { k_total += k_value; }
1054:            }
1055:            number Prandtl = fs.gas.mu * gmodel.Cp(fs.gas) / k_total;
1056:            signal += 4.0 * myConfig.viscous_factor * (fs.gas.mu + fs.mu_t)
1057:                * gam_eff / (Prandtl * fs.gas.rho)
1058:                * 1.0/(L_min^^2) * myConfig.viscous_signal_factor;
1059:        }
1060:        this.signal_parab = signal - this.signal_hyp; // store parabolic signal for STS
1061:        version(turbulence) {
1062:            number turbulent_signal = myConfig.turb_model.turbulent_signal_frequency(*fs);
1063:            turbulent_signal *= myConfig.turbulent_signal_factor;
1064:            signal = fmax(signal, turbulent_signal);
1065:            this.signal_parab = fmax(signal_parab, turbulent_signal);
1066:        }
1067:        version(MHD) {
1068:            if (myConfig.MHD) {
1069:                assert(myConfig.stringent_cfl, "MHD seems to only works if stringent_cfl is used.");
1070:                // Gas dynamics speed
1071:                // Ignoring flow and index directions, make the worst case assumptions.
1072:                number u_mag_sq = (fs.vel.x)^^2 + (fs.vel.y)^^2;
1073:                if (myConfig.dimensions == 3) { u_mag_sq += (fs.vel.z)^^2; }
1074:                number u_mag = sqrt(u_mag_sq);
1075:                // MHD signal speed
1076:                number B_mag_sq = (fs.B.x)^^2 + (fs.B.y)^^2 + (fs.B.z)^^2;
1077:                number ca2 = B_mag_sq / fs.gas.rho;
1078:                number cfast = sqrt(ca2 + (fs.gas.a)^^2);
1079:                signal = fmax(signal, (u_mag+cfast)/L_min);
1080:            }
1081:        }
1082:        return signal.re;
1083:    } // end signal_frequency()

326:void tetrahedron_properties(ref const(Vector3) p0, ref const(Vector3) p1,
327:                            ref const(Vector3) p2, ref const(Vector3) p3,
328:                            ref Vector3 centroid, ref number volume, ref number L_min)
329:// Variant including L_min calculation.
330:{
331:    centroid.set(0.25*(p0.x + p1.x + p2.x + p3.x),
332:                 0.25*(p0.y + p1.y + p2.y + p3.y),
333:                 0.25*(p0.z + p1.z + p2.z + p3.z));
334:    volume = tetrahedron_volume(p0, p1, p2, p3);
335:    number third = 1.0/3.0;
336:    L_min = pow(volume, third);
337:    Vector3 pmid = Vector3(third*(p0.x+p1.x+p2.x), third*(p0.y+p1.y+p2.y), third*(p0.z+p1.z+p2.z));
338:    L_min = fmin(L_min, 2.0*distance_between(pmid, centroid));
339:    pmid = Vector3(third*(p0.x+p1.x+p3.x), third*(p0.y+p1.y+p3.y), third*(p0.z+p1.z+p3.z));
340:    L_min = fmin(L_min, 2.0*distance_between(pmid, centroid));
341:    pmid = Vector3(third*(p1.x+p2.x+p3.x), third*(p1.y+p2.y+p3.y), third*(p1.z+p2.z+p3.z));
342:    L_min = fmin(L_min, 2.0*distance_between(pmid, centroid));
343:    pmid = Vector3(third*(p2.x+p0.x+p3.x), third*(p2.y+p0.y+p3.y), third*(p2.z+p0.z+p3.z));
344:    L_min = fmin(L_min, 2.0*distance_between(pmid, centroid));
345:} // end tetrahedron_properties()

