80:double nextXxxxTime(double now, Schedule!double dt_schedule)
81:{
82:    // Returns the absolute simulation time at which the next snapshot should be made.
83:    // Even if we have restarted the simulation from some intermediate time,
84:    // we should continue to get the originally-requested instances.
85:    double t = 0;
86:    while (t <= now) { t += dt_schedule.get_value(now); }
87:    return t;
